   198  int git_signature__parse(git_signature *sig, const char **buffer_out,
   199                  const char *buffer_end, const char *header, char ender)
   200  {
   201          const char *buffer = *buffer_out;
   202          const char *email_start, *email_end;
   203
   204          memset(sig, 0, sizeof(git_signature));
   205
   206          if (ender &&
   207                  (buffer_end = memchr(buffer, ender, buffer_end - buffer)) == NULL)
   208                  return signature_error("no newline given");
   209
   210          if (header) {
   211                  const size_t header_len = strlen(header);
   212
   213                  if (buffer + header_len >= buffer_end || memcmp(buffer, header, header_len) != 0)
   214                          return signature_error("expected prefix doesn't match actual");
   215
   216                  buffer += header_len;
   217          }
   218
   219          email_start = git__memrchr(buffer, '<', buffer_end - buffer);
   220          email_end = git__memrchr(buffer, '>', buffer_end - buffer);
   221
   222          if (!email_start || !email_end || email_end <= email_start)
   223                  return signature_error("malformed e-mail");
   224
   225          email_start += 1;
   226          sig->name = extract_trimmed(buffer, email_start - buffer - 1);
   227          sig->email = extract_trimmed(email_start, email_end - email_start);
   228
   229          /* Do we even have a time at the end of the signature? */
   230          if (email_end + 2 < buffer_end) {
   231                  const char *time_start = email_end + 2;
   232                  const char *time_end;
   233
   234                  if (git__strtol64(&sig->when.time, time_start, &time_end, 10) < 0) {
   235                          git__free(sig->name);
   236                          git__free(sig->email);
   237                          sig->name = sig->email = NULL;
   238                          return signature_error("invalid Unix timestamp");
   239                  }
   240
   241                  /* do we have a timezone? */
   242                  if (time_end + 1 < buffer_end) {
   243                          int offset, hours, mins;
   244                          const char *tz_start, *tz_end;
   245
   246                          tz_start = time_end + 1;
   247
   248                          if ((tz_start[0] != '-' && tz_start[0] != '+') ||
   249                                  git__strtol32(&offset, tz_start + 1, &tz_end, 10) < 0) {
   250                                  /* malformed timezone, just assume it's zero */
   251                                  offset = 0;
   252                          }
   253
   254                          hours = offset / 100;
   255                          mins = offset % 100;
   256
   257                          /*
   258                           * only store timezone if it's not overflowing;
   259                           * see http://www.worldtimezone.com/faq.html
   260                           */
   261                          if (hours <= 14 && mins <= 59) {
   262                                  sig->when.offset = (hours * 60) + mins;
   263                                  sig->when.sign = tz_start[0];
   264                                  if (tz_start[0] == '-')
   265                                          sig->when.offset = -sig->when.offset;
   266                          }
   267                  }
   268          }
   269
   270          *buffer_out = buffer_end + 1;
   271          return 0;
   272  }
